using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
abstract class DesignSheetForm:Form {
 protected readonly TabControl Pages=new NavigationTabs{Dock=DockStyle.Fill};protected readonly Dictionary<string,Control> Inputs=new Dictionary<string,Control>();protected bool Restoring;readonly string kind;readonly CalculationReportView report=new CalculationReportView{Dock=DockStyle.Fill};readonly Label status=new Label{Dock=DockStyle.Bottom,Height=40,Padding=new Padding(10)};
 protected DesignSheetForm(string title,string type){if(!AccessCodes.CanUseApp(type=="Wind-Design"||type=="RSA-Curve"?ProgramAccess.WindDesign:type=="Purlin-Design"?ProgramAccess.PurlinDesign:type=="Beam-Deflection"?ProgramAccess.BeamDeflection:ProgramAccess.TrussConnections))throw new Exception("Design Sheets access required.");kind=type;AppBrand.Apply(this);Text=title;ClientSize=new Size(1180,780);MinimumSize=new Size(820,600);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var tools=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,MinimumSize=new Size(0,52),Padding=new Padding(8),WrapContents=true};Action<string,Action> button=(text,action)=>{var b=new Button{Text=text,AutoSize=true,Height=38};b.Click+=async(s,e)=>{try{if(text=="Calculate"||text=="Export report file"||text=="Print preview"||text=="Export PDF")await PrepareDocumentAsync();action();}catch(Exception ex){status.Text=ex.Message;status.ForeColor=Color.Firebrick;}};tools.Controls.Add(b);};button("Calculate",Calculate);button("Save sheet XML",Save);button("Open sheet XML",Open);button("Export report to Excel",ExportExcel);button("Export report file",()=>ProfessionalReportExport.Show(this,BuildEngineeringReport()));button("Print preview",()=>{using(var document=BuildDocument())CalculationReportView.ShowReport(this,document);});button("Export PDF",()=>{using(var document=BuildDocument())using(var dialog=new SaveFileDialog{Filter="PDF|*.pdf",FileName=kind+".pdf"})if(dialog.ShowDialog(this)==DialogResult.OK)document.WritePdf(dialog.FileName);});/* equal-width command buttons (the theme sizes each button to its caption) */bool evening=false;Action evenCommands=()=>{if(evening)return;evening=true;try{var list=tools.Controls.OfType<Button>().ToList();if(list.Count==0)return;int widest=list.Max(x=>TextRenderer.MeasureText(x.Text??"",x.Font,Size.Empty,TextFormatFlags.SingleLine|TextFormatFlags.NoPrefix).Width+34+(x.Image==null?0:22));foreach(var x in list)if(x.MinimumSize.Width!=widest)x.MinimumSize=new Size(widest,Math.Max(38,x.MinimumSize.Height));}finally{evening=false;}};tools.Layout+=(s0,e0)=>evenCommands();Shown+=(s0,e0)=>evenCommands();Controls.Add(Pages);Controls.Add(tools);Controls.Add(status);var output=new TabPage("Calculation report");output.Controls.Add(report);Pages.TabPages.Add(output);TopTabLayout.AttachCommands(Pages,tools,this);
 #if !ADMIN_APP
 var renewal=new AccessRenewal(this);FormClosed+=(s,e)=>renewal.Dispose();
 #endif
 }
 protected FlowLayoutPanel Section(string title,string note){var page=new TabPage(title);var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(12,14,12,14),WrapContents=true};/* left edge matches the command buttons */page.Controls.Add(flow);if(!string.IsNullOrEmpty(note))flow.Controls.Add(new Label{Text=note,Width=1050,Height=40,Tag="FullWidth",Name="SectionNote",ForeColor=PowTheme.Muted,Margin=new Padding(0,0,0,10)});flow.Resize+=(sender,args)=>Arrange(flow);flow.ControlAdded+=(sender,args)=>{if(flow.IsHandleCreated)flow.BeginInvoke(new Action(()=>Arrange(flow)));};var output=Pages.TabPages[Pages.TabPages.Count-1];Pages.TabPages.Remove(output);Pages.TabPages.Add(page);Pages.TabPages.Add(output);Pages.SelectedIndex=0;return flow;}
 /* Field cards share one column grid and every full-width block spans exactly that grid, so the left and right edges
    line up; inputs always fit inside their card (owner, 19 November 2026: "di magkaka align", "putol yung text box"). */
 const int FieldGap=14,FieldMin=260;
 internal static void Arrange(FlowLayoutPanel flow){if(flow.IsDisposed||flow.FlowDirection!=FlowDirection.LeftToRight)return;int avail=flow.ClientSize.Width-flow.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-2;if(avail<120)return;
  int cols=Math.Max(1,Math.Min(5,(avail+FieldGap)/(FieldMin+FieldGap)));int w=(avail-cols*FieldGap)/cols;int full=cols*w+(cols-1)*FieldGap;
  flow.SuspendLayout();try{Control previous=null;foreach(Control item in flow.Controls){string tag=Convert.ToString(item.Tag);/* a full-width block always starts and ends its own row */if(tag=="FullWidth"){flow.SetFlowBreak(item,true);if(previous!=null)flow.SetFlowBreak(previous,true);}previous=item;
   if(tag=="DesignField"){item.Width=w;item.Margin=new Padding(0,0,FieldGap,12);foreach(Control inner in item.Controls)inner.Width=Math.Max(60,w-item.Padding.Horizontal-2);}
   else if(tag=="FullWidth"){item.Width=full;item.Margin=new Padding(0,item.Margin.Top,0,Math.Max(10,item.Margin.Bottom));if(item.Name=="SectionNote")item.Height=TextRenderer.MeasureText(item.Text,item.Font,new Size(full,0),TextFormatFlags.WordBreak).Height+6;}}}
  finally{flow.ResumeLayout(true);}}
 protected TextBox NumberField(FlowLayoutPanel panel,string key,string label,string value){var text=new TextBox{Text=value,Width=280};Field(panel,key,label,text);return text;}
 protected ComboBox Choice(FlowLayoutPanel panel,string key,string label,string[] values){var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=280,DropDownWidth=500};combo.Items.AddRange(values);combo.AutoCompleteSource=AutoCompleteSource.ListItems;combo.AutoCompleteMode=AutoCompleteMode.SuggestAppend;if(values.Length>0)combo.SelectedIndex=0;Field(panel,key,label,combo);return combo;}
 protected CheckBox Toggle(FlowLayoutPanel panel,string key,string label,bool value){var check=new CheckBox{Text=label,Checked=value,Width=280,Height=40};Field(panel,key,"",check);return check;}
 protected void Field(FlowLayoutPanel panel,string key,string label,Control input){var box=new FlowLayoutPanel{Width=310,Height=82,FlowDirection=FlowDirection.TopDown,WrapContents=false,BackColor=Color.White,Padding=new Padding(10,6,10,6),Margin=new Padding(0,0,14,12),Tag="DesignField"};if(!string.IsNullOrEmpty(label))box.Controls.Add(new Label{Text=label,Width=280,Height=30});if(input is CheckBox)input.Margin=new Padding(3,30,3,3);/* same height and input line as the other cards */box.Controls.Add(input);panel.Controls.Add(box);Inputs.Add(key,input);}
 protected string Value(string key){return Inputs[key].Text.Trim();}protected double Number(string key){double value;if(!double.TryParse(Value(key),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value))throw new Exception("Check "+key+"; enter a finite number with a decimal point.");return value;}
 protected virtual EngineeringReport BuildEngineeringReport(){return ProfessionalReportExport.FromText(BuildReport());}
 protected virtual CalculationDocument BuildDocument(){return CalculationDocument.FromText(BuildReport());}
 protected void AddResultPage(TabPage page){var output=Pages.TabPages[Pages.TabPages.Count-1];Pages.TabPages.Remove(output);Pages.TabPages.Add(page);Pages.TabPages.Add(output);}
 // Lets a sheet finish asynchronous work (for example map tiles) before a report is built.
 protected virtual System.Threading.Tasks.Task PrepareDocumentAsync(){return System.Threading.Tasks.Task.FromResult(true);}
 protected virtual bool OptionalSavedInput(string key){return false;}protected abstract string BuildReport();protected virtual void AfterRestore(){}protected virtual void WriteAdditionalState(XmlElement root){}protected virtual void ReadAdditionalState(XmlElement root){}
 public string CurrentReport(){return BuildReport();}
 void Calculate(){report.SetDocument(BuildDocument());status.ForeColor=PowTheme.Teal;status.Text="Calculated. Save sheet XML to keep inputs; exports contain the calculation report only.";Pages.SelectedIndex=Pages.TabCount-1;}
 void ExportExcel(){string text=BuildReport();using(var dialog=new SaveFileDialog{Filter="Excel workbook|*.xlsx",FileName=kind+"-Report.xlsx",OverwritePrompt=false})if(dialog.ShowDialog(this)==DialogResult.OK){using(var output=new ExcelLiveLink(dialog.FileName,true,false))output.UpdateDesignReport(kind,text);status.Text="Calculation report exported. Save sheet XML separately to retain editable inputs.";}}
 void Save(){using(var dialog=new SaveFileDialog{Filter="DTCE design sheet|*.design.xml",FileName=kind+".design.xml"})if(dialog.ShowDialog(this)==DialogResult.OK)File.WriteAllText(dialog.FileName,Snapshot());}
 void Open(){using(var dialog=new OpenFileDialog{Filter="DTCE design sheet|*.design.xml"})if(dialog.ShowDialog(this)==DialogResult.OK)Restore(File.ReadAllText(dialog.FileName));}
 internal string Snapshot(){var doc=new XmlDocument();var root=doc.CreateElement("DesignSheet");root.SetAttribute("type",kind);root.SetAttribute("version","1");doc.AppendChild(root);foreach(var pair in Inputs){var field=doc.CreateElement("Input");field.SetAttribute("key",pair.Key);field.InnerText=pair.Value is CheckBox?((CheckBox)pair.Value).Checked.ToString():pair.Value.Text;root.AppendChild(field);}WriteAdditionalState(root);return doc.OuterXml;}
 internal void Restore(string xml){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(new StringReader(xml),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=64000000}))doc.Load(reader);if(doc.DocumentElement.Name!="DesignSheet"||doc.DocumentElement.GetAttribute("type")!=kind||doc.DocumentElement.GetAttribute("version")!="1")throw new Exception("Choose a matching design-sheet file.");var values=new Dictionary<string,string>();foreach(XmlElement element in doc.DocumentElement.SelectNodes("Input")){string key=element.GetAttribute("key");if(!Inputs.ContainsKey(key)||values.ContainsKey(key))throw new Exception("Invalid/duplicate design input.");values[key]=element.InnerText;}foreach(var pair in Inputs)if(!values.ContainsKey(pair.Key)){if(!OptionalSavedInput(pair.Key))throw new Exception("Incomplete design sheet.");values[pair.Key]=pair.Value is CheckBox?((CheckBox)pair.Value).Checked.ToString():pair.Value.Text;}foreach(var pair in values){var combo=Inputs[pair.Key] as ComboBox;if(combo!=null&&!combo.Items.Contains(pair.Value))throw new Exception("Saved profile or selection is unavailable: "+pair.Key);if(Inputs[pair.Key] is CheckBox)bool.Parse(pair.Value);}ReadAdditionalState(doc.DocumentElement);Restoring=true;try{foreach(var pair in values){var check=Inputs[pair.Key] as CheckBox;if(check!=null)check.Checked=bool.Parse(pair.Value);else Inputs[pair.Key].Text=pair.Value;}}finally{Restoring=false;}AfterRestore();Calculate();}
}
class PurlinDesignForm:DesignSheetForm {
 readonly ComboBox profiles;readonly CheckBox verified;readonly TextBox ix,iy,ixy,sx,sy;
 public PurlinDesignForm():base("Purlin Design | Workbook ASD checks","Purlin-Design"){
  var geometry=Section("Geometry & loads","Based on PS Design of Purlin.xlsm. Signed wind normal to roof; negative values represent uplift/suction. This sheet evaluates the listed workbook flexure/deflection checks, not the complete cold-formed member design.");NumberField(geometry,"Name","Member / purlin name","Purlin");profiles=Choice(geometry,"Profile","Regan handbook purlin profile",SteelCatalog.Profiles.Where(p=>p.Kind=="Purlin").Select(p=>p.Name).ToArray());geometry.Controls.Add(new SteelSectionPreview(()=>SteelCatalog.Find(profiles.Text),()=>false,profiles));Choice(geometry,"Support","Support",new[]{"Simply supported","Cantilever"});NumberField(geometry,"Span","Span / cantilever length m","5");NumberField(geometry,"Spacing","Purlin spacing m","0.4");NumberField(geometry,"Angle","Roof angle deg","13");Choice(geometry,"SagRods","Effective sag rods",new[]{"0","1","2"});Choice(geometry,"Ceiling","Ceiling type",new[]{"Not supporting ceiling","Supporting nonplaster ceiling","Supporting plaster ceiling"});NumberField(geometry,"Dead","Superimposed dead load kPa","0.35");NumberField(geometry,"Live","Roof live load kPa","1");NumberField(geometry,"WindPressure","Signed pressure kPa","0");NumberField(geometry,"WindSuction","Signed suction kPa","0");NumberField(geometry,"Fy","Specified yield strength MPa","248");NumberField(geometry,"E","Modulus of elasticity MPa","200000");Toggle(geometry,"AlternateIncrease","Workbook alternate 4/3 allowable increase",true);
  var properties=Section("Section properties","Handbook PDF pp.43-44 supplies dimensions and mass only. Auto properties idealize nonoverlapping rectangular plates and neglect bend radii. For final use enter verified properties with the same geometric axes/centroid; nonzero Ixy must be retained for Z shapes. Additional buckling, shear and connection checks remain outside this sheet.");verified=Toggle(properties,"Verified","Use verified section properties",false);ix=NumberField(properties,"Ix","Ix mm4","1");iy=NumberField(properties,"Iy","Iy mm4","1");ixy=NumberField(properties,"Ixy","Ixy mm4 (signed)","0");sx=NumberField(properties,"Sx","Sx mm3","1");sy=NumberField(properties,"Sy","Sy mm3","1");profiles.SelectedIndexChanged+=(s,e)=>{if(!Restoring){verified.Checked=false;UpdateProperties();}};verified.CheckedChanged+=(s,e)=>{if(!Restoring)UpdateProperties();};UpdateProperties();
 }
 void UpdateProperties(){var p=PurlinProperties.Calculate(SteelCatalog.Find(profiles.Text));if(!verified.Checked){ix.Text=p.Ix.ToString("R",CultureInfo.InvariantCulture);iy.Text=p.Iy.ToString("R",CultureInfo.InvariantCulture);ixy.Text=p.Ixy.ToString("R",CultureInfo.InvariantCulture);sx.Text=p.Sx.ToString("R",CultureInfo.InvariantCulture);sy.Text=p.Sy.ToString("R",CultureInfo.InvariantCulture);}foreach(var text in new[]{ix,iy,ixy,sx,sy})text.ReadOnly=!verified.Checked;}
 protected override void AfterRestore(){UpdateProperties();}
 protected override string BuildReport(){var profile=SteelCatalog.Find(Value("Profile"));var p=PurlinProperties.Calculate(profile);if(verified.Checked){p.Ix=Number("Ix");p.Iy=Number("Iy");p.Ixy=Number("Ixy");p.Sx=Number("Sx");p.Sy=Number("Sy");p.Verified=true;}var input=new PurlinDesignInput{Name=Value("Name"),Profile=profile,Properties=p,Support=Value("Support"),Span=Number("Span"),Spacing=Number("Spacing"),Angle=Number("Angle"),SagRods=int.Parse(Value("SagRods")),Ceiling=Value("Ceiling"),Dead=Number("Dead"),Live=Number("Live"),WindPressure=Number("WindPressure"),WindSuction=Number("WindSuction"),Fy=Number("Fy"),E=Number("E"),AlternateIncrease=((CheckBox)Inputs["AlternateIncrease"]).Checked};return PurlinDesigner.Report(input,PurlinDesigner.Calculate(input));}
}
}
